class Solution {
public:
    string largestWordCount(vector<string>& messages, vector<string>& senders) {
        unordered_map<string, int> cnt;
        int n = messages.size();
        for (int i = 0; i < n; i++) {
            int words = 1;
            for (char c : messages[i]) {
                if (c == ' ') words++;
            }
            cnt[senders[i]] += words;
        }
        string best;
        int bestCnt = -1;
        for (auto& [name, c] : cnt) {
            if (c > bestCnt || (c == bestCnt && name > best)) {
                bestCnt = c;
                best = name;
            }
        }
        return best;
    }
};
